TICOOK COMPTON", "type": "LIGUE_CIVILE"}, {"nom": "Club de soccer Énergie de Centre-Mauricie", "source_cle": "CLUB DE SOCCER ÉNERGIE CENTRE MAURICIE", "type": "LIGUE_CIVILE"}, {"nom": "Comité de basketball Saint-Laurent", "source_cle": "St-Laurent Delta", "type": "LIGUE_CIVILE"}, {"nom": "Cosmos de Granby", "source_cle": "COSMOS DE GRANBY", "type": "LIGUE_CIVILE"}, {"nom": "Downtown Community Blues", "source_cle": "DC Blues", "type": "LIGUE_CIVILE"}, {"nom": "FC Anjou", "source_cle": "FC ANJOU", "type": "LIGUE_CIVILE"}, {"nom": "FC Boréal", "source_cle": "FC BORÉAL", "type": "LIGUE_CIVILE"}, {"nom": "FC Challenger", "source_cle": "FC CHALLENGER", "type": "LIGUE_CIVILE"}, {"nom": "FC Gatineau", "source_cle": "FC GATINEAU", "type": "LIGUE_CIVILE"}, {"nom": "FC Laval", "source_cle": "FC LAVAL", "type": "LIGUE_CIVILE"}, {"nom": "FC Loro", "source_cle": "FC LORO", "type": "LIGUE_CIVILE"}, {"nom": "FC Petite-Nation", "source_cle": "FC PETITE-NATION", "type": "LIGUE_CIVILE"}, {"nom": "FC Saint-Hyacinthe", "source_cle": "FC SAINT-HYACINTHE", "type": "LIGUE_CIVILE"}, {"nom": "FC Saint-Léonard", "source_cle": "ST-LEONARD SOCCER ASSOCIATION", "type": "LIGUE_CIVILE"}, {"nom": "FC Trois-Lacs", "source_cle": "FC TROIS-LACS", "type": "LIGUE_CIVILE"}, {"nom": "FC Waterloo", "source_cle": "FC WATERLOO", "type": "LIGUE_CIVILE"}, {"nom": "FC des Vallées", "source_cle": "FC DES VALLÉES", "type": "LIGUE_CIVILE"}, {"nom": "Football Club Morin-Heights", "source_cle": "F.C. MORIN-HEIGHTS", "type": "LIGUE_CIVILE"}, {"nom": "Fédération sportive Salaberry", "source_cle": "FÉDÉRATION SPORTIVE DE SALABERRY", "type": "LIGUE_CIVILE"}, {"nom": "Galaxie de La Prairie", "source_cle": "LA PRAIRIE SOCCER CLUB", "type": "LIGUE_CIVILE"}, {"nom": "Hornets de Sun Youth", "source_cle": "Sun Youth Hornets", "type": "LIGUE_CIVILE"}, {"nom": "Lachine Soccer Club", "source_cle": "LACHINE SC", "type": "LIGUE_CIVILE"}, {"nom": "Lakeshore SC", "source_cle": "LAKESHORE SOCCER CLUB", "type": "LIGUE_CIVILE"}, {"nom": "Lanaudière Nord", "source_cle": "C.S. LANAUDIÈRE-NORD", "type": "LIGUE_CIVILE"}, {"nom": "Les Celtics de l'Ouest de Portneuf", "source_cle": "CELTICS DE L'OUEST DE PORTNEUF", "type": "LIGUE_CIVILE"}, {"nom": "Optimum de Victoriaville", "source_cle": "CLUB DE SOCCER OPTIMUM VICTORIAVILLE", "type": "LIGUE_CIVILE"}, {"nom": "Panellinios St-Michel FC", "source_cle": "PANELLINIOS ST MICHEL FC", "type": "LIGUE_CIVILE"}, {"nom": "Phénix des Rivières", "source_cle": "PHÉNIX DES RIVIÈRES", "type": "LIGUE_CIVILE"}, {"nom": "Red Rush", "source_cle": "DCB Red Rush", "type": "LIGUE_CIVILE"}, {"nom": "Red Rush", "source_cle": "DCB Red rush", "type": "LIGUE_CIVILE"}, {"nom": "Révolution", "source_cle": "Révolution des Laurentides", "type": "LIGUE_CIVILE"}, {"nom": "Révolution FC", "source_cle": "REVOLUTION FC", "type": "LIGUE_CIVILE"}, {"nom": "Saint-Félix-de-Valois", "source_cle": "A.S. ST-FÉLIX-DE-VALOIS", "type": "LIGUE_CIVILE"}, {"nom": "Saint-Germain-de-Grantham", "source_cle": "RAPIDES DE ST-GERMAIN", "type": "LIGUE_CIVILE"}, {"nom": "Soccer Pointe-Claire", "source_cle": "SOCCER POINTE-CLAIRE", "type": "LIGUE_CIVILE"}, {"nom": "Soccer de Soulanges", "source_cle": "CLUB DE SOCCER SOULANGES", "type": "LIGUE_CIVILE"}, {"nom": "Tornades de Longueuil", "source_cle": "Tornades", "type": "LIGUE_CIVILE"}, {"nom": "Tornades de Longueuil", "source_cle": "Tornades Black", "type": "LIGUE_CIVILE"}, {"nom": "Tornades de Longueuil", "source_cle": "Tornades Grey", "type": "LIGUE_CIVILE"}, {"nom": "Tornades de Longueuil", "source_cle": "Tornades de Longueuil", "type": "LIGUE_CIVILE"}, {"nom": "Union Lanaudière-Sud", "source_cle": "UNION LANAUDIÈRE SUD", "type": "LIGUE_CIVILE"}, {"nom": "West Island Lakers Basketball Association", "source_cle": "West Island Lakers", "type": "LIGUE_CIVILE"}, {"nom": "Westmount Soccer Club", "source_cle": "WESTMOUNT SOCCER CLUB", "type": "LIGUE_CIVILE"}]}$donnees$;
  d        jsonb;
  v_op     uuid;
  n_new    int;
  n_geo    int;
  n_src    int;
  v_avant  jsonb;
  v_txt    text;
begin
  if extract(isodow from now() at time zone 'America/Toronto') = 2
     or (extract(isodow from now() at time zone 'America/Toronto') = 3
         and extract(hour from now() at time zone 'America/Toronto') < 5) then
    raise exception 'NEXUS: pas de prod le mardi, ni le mercredi avant 5 h';
  end if;
  if md5(v_brut) <> 'ca684af884330e487699f581c4adfef6' then
    raise exception 'NEXUS: données du lot 2 altérées (md5 %)', md5(v_brut);
  end if;
  d := v_brut::jsonb;
  if to_regclass('public.organisations_sources') is null then
    raise exception 'NEXUS: lot 1 civil absent (organisations_sources)';
  end if;
  if exists (select 1 from public.admin_operations o where o.operation = 'CIVIL_ORGANISATIONS_CREEES'
              and not exists (select 1 from public.admin_operations a where a.operation = 'CIVIL_ORGANISATIONS_ANNULEES'
                                and a.details->>'op' = o.id::text)) then
    raise exception 'NEXUS: lot 2 déjà appliqué (opération non annulée)';
  end if;

  create temp table _l2_new on commit drop as
    select gen_random_uuid() as id, x.* from jsonb_to_recordset(d->'nouvelles')
      as x(nom text, region text, city text, lat float8, lng float8, sport text, sources text[]);
  create temp table _l2_geo on commit drop as
    select x.*, s.id, s.lat as lat_avant, s.lng as lng_avant, s.geo_source as geo_avant
      from jsonb_to_recordset(d->'geo_existantes') as x(nom text, type text, lat float8, lng float8)
      left join public.schools s on s.name = x.nom and s.type = x.type;
  create temp table _l2_src on commit drop as
    select x.*, s.id as school_id
      from jsonb_to_recordset(d->'sources_existantes') as x(nom text, type text, source_cle text)
      left join public.schools s on s.name = x.nom and s.type = x.type;

  -- Gardes d'avant
  select count(*) into n_new from _l2_new;
  if n_new <> 201 then raise exception 'NEXUS: % organisations à créer, attendu 201', n_new; end if;
  select string_agg(n.nom, ' ; ') into v_txt from _l2_new n
   where exists (select 1 from public.schools s where lower(s.name) = lower(n.nom));
  if v_txt is not null then raise exception 'NEXUS: existe déjà : %', v_txt; end if;
  select string_agg(nom, ' ; ') into v_txt from (
    select x.nom from jsonb_to_recordset(d->'geo_existantes') as x(nom text, type text)
     where (select count(*) from public.schools s where s.name = x.nom and s.type = x.type) <> 1
    union
    select x.nom from jsonb_to_recordset(d->'sources_existantes') as x(nom text, type text)
     where (select count(*) from public.schools s where s.name = x.nom and s.type = x.type) <> 1) z;
  if v_txt is not null then raise exception 'NEXUS: organisation existante introuvable ou en double : %', v_txt; end if;
  select string_agg(nom, ' ; ') into v_txt from _l2_geo where lat_avant is not null;
  if v_txt is not null then raise exception 'NEXUS: déjà géocodée (jamais d''écrasement) : %', v_txt; end if;

  -- Journal d'abord : les correspondances le référencent
  select jsonb_agg(jsonb_build_object('id', id, 'lat', lat_avant, 'lng', lng_avant, 'geo_source', geo_avant,
                                      'lat_pose', lat, 'lng_pose', lng) order by nom)
    into v_avant from _l2_geo;
  insert into public.admin_operations (operation, motif, details, par)
  values ('CIVIL_ORGANISATIONS_CREEES',
          'Import civil 2026-27, lot 2 : organisations civiles créées (liste validée par BP) + géocodage approximatif par ville',
          jsonb_build_object('lot', 2, 'md5_donnees', 'ca684af884330e487699f581c4adfef6',
                             'nouvelles_ids', (select jsonb_agg(id order by nom) from _l2_new),
                             'nouvelles_geocodees', (select count(*) from _l2_new where lat is not null),
                             'geo_existantes', v_avant,
                             'methode_geo', 'moyenne des écoles / cégeps géocodés de la ville (prod, relevé du 2026-10-26)'),
          (select id from public.users where email = 'bptds22@gmail.com'))
  returning id into v_op;

  insert into public.schools (id, name, type, region, city, lat, lng, geo_source)
  select id, nom, 'LIGUE_CIVILE', region, city, lat, lng, case when lat is not null then 'approx' end from _l2_new;
  get diagnostics n_new = row_count;

  update public.schools s set lat = g.lat, lng = g.lng, geo_source = 'approx', updated_at = now()
    from _l2_geo g where s.id = g.id and s.lat is null;
  get diagnostics n_geo = row_count;

  insert into public.organisations_sources (source_nom, source_cle, school_id, operation_id)
  select 'INVENTAIRE', unnest(sources), id, v_op from _l2_new
  union all
  select 'INVENTAIRE', source_cle, school_id, v_op from _l2_src;
  get diagnostics n_src = row_count;

  -- Gardes d'après
  if n_new <> 201 or n_geo <> 86 or n_src <> 489 then
    raise exception 'NEXUS: comptes inattendus — créées %, géocodées %, correspondances % (attendu 201 / 86 / 489)',
      n_new, n_geo, n_src;
  end if;
  if (select count(*) from public.schools where id in (select id from _l2_new) and type = 'LIGUE_CIVILE') <> 201 then
    raise exception 'NEXUS: organisations créées introuvables';
  end if;
  raise notice 'NEXUS: lot 2 — % organisations créées (% géocodées), % existantes géocodées, % correspondances (op %)',
    n_new, (select count(*) from _l2_new where lat is not null), n_geo, n_src, v_op;
end $lot2$;
